import base64, shutil, datetime, sys, os
ts = datetime.datetime.now().strftime('%Y%m%d_%H%M%S')

def detecta_eol(path):
    with open(path, 'rb') as f:
        data = f.read()
    return '\r\n' if data.count(b'\r\n') > 0 else '\n'

# 1) Cria o arquivo novo WhatsAppAutomatico.tsx
os.makedirs('src/components', exist_ok=True)
ref_dir = 'src/pages'
ref_files = [f for f in os.listdir(ref_dir) if f.endswith('.tsx')] if os.path.isdir(ref_dir) else []
eol_projeto = detecta_eol(os.path.join(ref_dir, ref_files[0])) if ref_files else '\n'
newfile_b64_lf = ''
newfile_content = base64.b64decode(newfile_b64_lf).decode('utf-8')
if eol_projeto == '\r\n':
    newfile_content = newfile_content.replace('\r\n', '\n').replace('\n', '\r\n')
with open('src/components/WhatsAppAutomatico.tsx', 'w', encoding='utf-8', newline='') as f:
    f.write(newfile_content)
print('Criado: src/components/WhatsAppAutomatico.tsx (EOL detectado:', repr(eol_projeto), ')')

edits = [
    {'file': 'src/pages/ConfiguracaoPage.tsx', 'label': 'Import WhatsAppAutomatico component', 'old_b64': 'aW1wb3J0IHRvYXN0IGZyb20gJ3JlYWN0LWhvdC10b2FzdCc7', 'new_b64': 'aW1wb3J0IHRvYXN0IGZyb20gJ3JlYWN0LWhvdC10b2FzdCc7CmltcG9ydCBXaGF0c0FwcEF1dG9tYXRpY28gZnJvbSAnLi4vY29tcG9uZW50cy9XaGF0c0FwcEF1dG9tYXRpY28nOw=='},
    {'file': 'src/pages/ConfiguracaoPage.tsx', 'label': 'Insert WhatsAppAutomatico card before Asaas', 'old_b64': 'ICAgICAgICAgIDwvZGl2PgoKICAgICAgICAgIHsvKiBBc2FhcyAqL30=', 'new_b64': 'ICAgICAgICAgIDwvZGl2PgoKICAgICAgICAgIHsvKiBXaGF0c0FwcCBBdXRvbcOhdGljbyAoRXZvbHV0aW9uIEFQSSkgKi99CiAgICAgICAgICA8V2hhdHNBcHBBdXRvbWF0aWNvIC8+CgogICAgICAgICAgey8qIEFzYWFzICovfQ=='},
]

backed_up = set()
for e in edits:
    fname = e['file']
    if fname not in backed_up:
        shutil.copy(fname, fname + f'.bak_{ts}')
        backed_up.add(fname)
        print('Backup:', fname + f'.bak_{ts}')

ok = True
for e in edits:
    fname = e['file']
    eol = detecta_eol(fname)
    old = base64.b64decode(e['old_b64']).decode('utf-8')
    new = base64.b64decode(e['new_b64']).decode('utf-8')
    if eol == '\r\n':
        old = old.replace('\r\n', '\n').replace('\n', '\r\n')
        new = new.replace('\r\n', '\n').replace('\n', '\r\n')
    with open(fname, 'r', encoding='utf-8', newline='') as f:
        content = f.read()
    count = content.count(old)
    if count != 1:
        print(f'AVISO: {count} ocorrencias (esperado 1): {e["label"]} em {fname}')
        ok = False
        continue
    content = content.replace(old, new)
    with open(fname, 'w', encoding='utf-8', newline='') as f:
        f.write(content)
    print('OK:', e['label'], 'em', fname, '(EOL:', repr(eol), ')')

if ok:
    print()
    print('Tudo aplicado com sucesso. Proximo passo: npm run build')
else:
    print()
    print('ATENCAO: algum patch nao aplicou. NAO faca commit ainda -- me avise com a mensagem acima.')
    sys.exit(1)